// Metadata only, under /JSTACK. Never downloads file contents.
const first = $input.first().json;
const body = first.body || first;
const request_id = (typeof body.request_id === 'string' && body.request_id.length <= 100) ? body.request_id : undefined;
const fail = (code, message, status_code = 400) => [{ json: { valid: false, status_code, error: { code, message }, request_id } }];
const isIso = (v) => typeof v === 'string' && v.trim() !== '' && !isNaN(new Date(v).getTime());
const ROOT = '/JSTACK';
const cursor = body.cursor == null || body.cursor === '' ? null : String(body.cursor);
if (cursor) {
  if (cursor.length > 2000) return fail('VALIDATION_ERROR', 'cursor too long');
  return [{ json: { valid: true, request_id, req: { url: 'https://api.dropboxapi.com/2/files/list_folder/continue', body: { cursor } } } }];
}
const path = body.path == null || body.path === '' ? ROOT : String(body.path);
if (!(path.toLowerCase() === ROOT.toLowerCase() || path.toLowerCase().startsWith(ROOT.toLowerCase() + '/')) || path.includes('..')) {
  return fail('VALIDATION_ERROR', 'path must be ' + ROOT + ' or inside it', 403);
}
let limit = parseInt(body.limit ?? 500, 10); if (isNaN(limit)) limit = 500; limit = Math.max(1, Math.min(2000, limit));
return [{ json: { valid: true, request_id, req: { url: 'https://api.dropboxapi.com/2/files/list_folder',
  body: { path, recursive: body.recursive !== false, limit, include_deleted: false, include_non_downloadable_files: false } } } }];

const v = $('Validate Input').first().json;
const r = $input.first().json || {};
const sc = r.statusCode;
const err = (code, message, status_code) => [{ json: { ok: false, status_code, request_id: v.request_id, error: { code, message } } }];
// Dropbox answers 409 path/not_found for a missing folder. /JSTACK itself not existing yet just
// means nothing has been filed there (CONTRACT.md §2: files live under /JSTACK/): an empty list.
const notFound = sc === 409 && JSON.stringify(r.body || '').includes('not_found');
const askedRoot = !(v.req.body && v.req.body.cursor) && String((v.req.body && v.req.body.path) || '').toLowerCase() === '/jstack';
if (notFound && askedRoot) return [{ json: { ok: true, response: { ok: true, request_id: v.request_id, data: { count: 0, files: [], has_more: false, cursor: null, root_missing: true } } } }];
if (notFound) return err('NOT_FOUND', 'folder not found under /JSTACK', 404);
if (sc === 409) return err('UPSTREAM_ERROR', 'Dropbox refused: ' + JSON.stringify(r.body || '').slice(0, 200), 502);
if (!(sc >= 200 && sc < 300)) return err('UPSTREAM_ERROR', 'Dropbox answered ' + sc + ': ' + JSON.stringify(r.body || '').slice(0, 300), 502);
const b = r.body || {};
const files = (b.entries || []).filter((e) => e['.tag'] === 'file').map((e) => {
  const path = e.path_display || e.path_lower;
  const folder = path.slice(0, path.lastIndexOf('/')) || '/';
  return { id: e.id, name: e.name, path, folder, size: e.size ?? null, modified: e.server_modified || e.client_modified || null,
    content_hash: e.content_hash || null, web_url: 'https://www.dropbox.com/home' + encodeURI(folder) + '?preview=' + encodeURIComponent(e.name) };
});
return [{ json: { ok: true, response: { ok: true, request_id: v.request_id, data: { count: files.length, files, has_more: !!b.has_more, cursor: b.cursor || null } } } }];
